import re
import numpy as np

# all-MiniLM-L6-v2 needs PyTorch and a model download, which this sandbox cannot do.
# encode() is a tiny offline stand-in that returns unit-length vectors.
TOPIC_WORDS = {
    0: {"refund", "refunds", "money", "back", "return", "returns", "purchase"},
    1: {"shipping", "delivery", "free", "orders", "ship", "euros", "threshold"},
    2: {"support", "help", "call", "weekdays", "contact", "available", "hours"},
}


def encode(text):
    vec = np.full(4, 0.01)
    for word in re.findall(r"[a-z]+", text.lower()):
        for dim, words in TOPIC_WORDS.items():
            if word in words:
                vec[dim] += 1.0
                break
        else:
            vec[3] += 0.1
    return vec / np.linalg.norm(vec)


def retrieve_top_k(question, chunks, k=2):
    """The retrieval stage from the previous exercise: the k most similar chunks, best first."""
    q = encode(question)
    scores = [float(np.dot(q, encode(c))) for c in chunks]
    order = sorted(range(len(chunks)), key=lambda i: scores[i], reverse=True)
    return [chunks[i] for i in order[:k]]


def build_prompt(question, chunks, k=2):
    """Retrieve the top-k evidence chunks and assemble a grounded RAG prompt."""
    evidence = "\n".join(retrieve_top_k(question, chunks, k))
    return f"Answer using ONLY the context below.\n\nContext:\n{evidence}\n\nQuestion: {question}"


chunks = [
    "Refunds are issued within 14 days of purchase.",
    "Shipping is free for orders over 50 euros.",
    "Support is available on weekdays from 9 to 5.",
]
print(build_prompt("Can I get my money back?", chunks, k=1))
